SELECT
    DISTINCT c.*,  supplier.name  as supplierName,
         CASE
            when  (COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0))>0
             then  (COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0))
else null end as  assetContractAmount,


             COALESCE(SUM(cd.payment_price) OVER (PARTITION BY c.id), 0) AS total_detail_amount,
             CASE
                 WHEN COALESCE(c.amount, 0) = 0 OR COALESCE(SUM(cd.payment_price) OVER (PARTITION BY c.id), 0) = 0 THEN 0
                 ELSE ROUND(CAST((COALESCE(SUM(cd.payment_price) OVER (PARTITION BY c.id), 0) / COALESCE(c.amount, 0)) * 100 AS numeric ),2)
                 END AS paymentProgress
FROM
    contract_info c
        left join supplier   on supplier.uid= c.supplier_uid
        LEFT JOIN
    contract_info_item cd ON c.id = cd.contract_id



            AND (
            c.institution_uid IN

                #{item}

            OR c.hospital_uid IN

                #{item}

            OR c.site_uid IN

                #{item}

            OR c.tenant_uid IN

                #{item}


            )


            and   c.name like concat('%',#{name},'%')


            and   c.report_num like concat('%',#{reportNum},'%')


            and   c.contract_type =#{contractType}


            and   supplier.name like concat('%',#{supplierName},'%')


            and   c.contract_num like concat('%',#{contractNum},'%')





                    and  c.contract_status = 'COMPLETE'


                    and (  c.contract_status  != 'COMPLETE' or c.contract_status  is null  )





           and   COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0) >=#{assetContractAmountGTE}


           and  COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0)  <=  #{assetContractAmountLTE}



            and   c.expect_arrival_date >= #{expectArrivalDateGTE}


            and c.expect_arrival_date <=   #{expectArrivalDateGTE}


            and   c.start_date >= #{startDateGTE}


            and c.start_date <=   #{startDateLTE}


            and   c.end_date >= #{endDateGTE}


            and c.end_date <=   #{endDateLTE}




    ORDER BY ${orderBy}

LIMIT #{page} OFFSET #{offset}

SELECT

    count(*) from
contract_info c
left join supplier   on supplier.uid= c.supplier_uid



        AND (
        c.institution_uid IN

            #{item}

        OR c.hospital_uid IN

            #{item}

        OR c.site_uid IN

            #{item}

        OR c.tenant_uid IN

            #{item}


        )


        and   c.name like concat('%',#{name},'%')


        and   c.report_num like concat('%',#{reportNum},'%')


        and   c.contract_type =#{contractType}


        and   supplier.name like concat('%',#{supplierName},'%')


        and   c.contract_num like concat('%',#{contractNum},'%')





                and  c.contract_status = 'COMPLETE'


                and (  c.contract_status  != 'COMPLETE' or c.contract_status  is null  )





        and   COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0) >=#{assetContractAmountGTE}


        and  COALESCE(c.amount, 0) + COALESCE(c.supplementary_amount, 0)  <=  #{assetContractAmountLTE}



        and   c.expect_arrival_date >= #{expectArrivalDateGTE}


        and c.expect_arrival_date <=   #{expectArrivalDateGTE}


        and   c.start_date >= #{startDateGTE}


        and c.start_date <=   #{startDateLTE}


        and   c.end_date >= #{endDateGTE}


        and c.end_date <=   #{endDateLTE}
